def get(n):return json.loads((P/n).read_text())
def mdtable(head,rows):
 return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join('---' for _ in head)+'|']+['| '+' | '.join(str(v) for v in r)+' |' for r in rows])
def percent(a,b):return f'{100*a/b:.2f}%' if b else '—'
def lookup_rates(group):
 rows=[r for r in csv.DictReader((P/'association-rates.csv').open()) if r['group']==group]
 return {(r['entity'],r['split']):r for r in rows}
def ratecell(r):
 a,b=int(r['failed']),int(r['attempted'])
 return f'{a:,}/{b:,} ({percent(a,b)})' if b else '—'
def rate_table(group,minimum=0):
 index=lookup_rates(group);names=sorted(n for n,sp in index if sp=='all' and int(index[n,sp]['eligible'])>=minimum)
 return mdtable([dict(pet='Pet',food='Food purchased',action='Action occurring in the turn')[group],'All misses / attempted','Dev','Held-out'],
    [[n]+[ratecell(index[n,sp]) if (n,sp) in index else '—' for sp in ('all','dev','heldout')] for n in names])
